package api

// The Christmas family in each client's view (round 4 of backlog B489). The
// family fills from what every client can play first, and its floor, the
// owner's rule (15 tracks at least, from 3 albums or 3 artists), holds for
// what each request is sent: a view the format gate leaves below it is not
// sent the family. Every library here is regenerated by the real regenerator
// and served through the real router, in season, to a client that declares
// nothing, WavPack, Monkey's Audio and both.

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"path"
	"path/filepath"
	"slices"
	"testing"
	"time"

	"github.com/acoseac/1-bit-bridge/internal/auth"
	"github.com/acoseac/1-bit-bridge/internal/config"
	"github.com/acoseac/1-bit-bridge/internal/formatgate"
	"github.com/acoseac/1-bit-bridge/internal/manifest"
	"github.com/acoseac/1-bit-bridge/internal/smartplaylistgen"
)

// xmasView is a client the views tests ask as: the X-Bridge-Formats lines it
// sends.
type xmasView struct {
	name    string
	formats []string
}

var xmasViews = []xmasView{
	{"nothing", nil},
	{"WavPack", []string{"wavpack"}},
	{"APE", []string{"ape"}},
	{"both", []string{"wavpack, ape"}},
}

// takes reports whether the view is served the track at p.
func (v xmasView) takes(p string) bool { return formatgate.Parse(v.formats).Takes(p) }

// xmasAlbumOf is n Christmas tracks of one album in the folder dir, each a
// file of ext by the artist artistOf(i) gives.
func xmasAlbumOf(dir, album, ext string, n int, artistOf func(int) string) []*manifest.Track {
	out := make([]*manifest.Track, 0, n)
	for i := 0; i < n; i++ {
		out = append(out, &manifest.Track{
			Path: fmt.Sprintf("%s/%02d%s", dir, i+1, ext), Size: 1, ModTime: time.Unix(1, 0),
			Title: fmt.Sprintf("%s %d", album, i+1), Artist: artistOf(i), Album: album, Genre: "Christmas",
		})
	}
	return out
}

// xmasSingles is n Christmas files of ext, each a single of its own by a
// singer of its own, under the folder dir.
func xmasSingles(dir, ext string, n int) []*manifest.Track {
	out := make([]*manifest.Track, 0, n)
	for i := 0; i < n; i++ {
		out = append(out, &manifest.Track{
			Path: fmt.Sprintf("%s/%04d%s", dir, i, ext), Size: 1, ModTime: time.Unix(1, 0),
			Title: fmt.Sprintf("Song %04d", i), Artist: fmt.Sprintf("%s singer %04d", dir, i),
			Album: fmt.Sprintf("%s single %04d", dir, i), Genre: "Christmas",
		})
	}
	return out
}

func byOne(name string) func(int) string { return func(int) string { return name } }

func pathsOfTracks(tracks []*manifest.Track) []string {
	out := make([]string, 0, len(tracks))
	for _, tr := range tracks {
		out = append(out, tr.Path)
	}
	return out
}

// xmasViewsServer stores tracks, runs the regenerator on 20 November 2026
// with analysis off, and serves the feed through the real router on 24
// December. get answers the Christmas family a view is sent: its paths in
// order, and whether it was sent at all.
func xmasViewsServer(t *testing.T, tracks []*manifest.Track) (get func(t *testing.T, v xmasView) ([]string, bool)) {
	t.Helper()
	ctx := context.Background()
	mstore := openFeedStore(t)
	if err := mstore.UpsertTrackBatch(ctx, tracks); err != nil {
		t.Fatal(err)
	}
	built := time.Date(2026, 11, 20, 12, 0, 0, 0, time.UTC)
	if _, err := smartplaylistgen.Regenerate(ctx, mstore, smartplaylistgen.DefaultOptions(built.UnixNano(), false)); err != nil {
		t.Fatal(err)
	}
	return xmasFeedOf(t, mstore)
}

// xmasFeedOf serves mstore's cached feed through the real router on 24
// December 2026, as xmasViewsServer's get answers.
func xmasFeedOf(t *testing.T, mstore *manifest.Store) func(t *testing.T, v xmasView) ([]string, bool) {
	t.Helper()
	dir := t.TempDir()
	cfg := &config.Config{LibraryRoots: []string{dir}, DataDir: dir, ListenAddress: ":7788", LibraryName: "T"}
	tokens, err := auth.OpenStore(filepath.Join(dir, "tokens.json"))
	if err != nil {
		t.Fatal(err)
	}
	raw, _, err := tokens.Mint("views")
	if err != nil {
		t.Fatal(err)
	}
	srv := New(cfg, tokens, nil, "fp").WithSmartPlaylistStore(mstore)
	inSeason := time.Date(2026, 12, 24, 18, 0, 0, 0, time.UTC)
	srv.clockNow = func() time.Time { return inSeason }
	hs := httptest.NewServer(srv.Handler())
	t.Cleanup(hs.Close)
	return func(t *testing.T, v xmasView) ([]string, bool) {
		t.Helper()
		req, err := http.NewRequest(http.MethodGet, hs.URL+"/v1/smart-playlists", nil)
		if err != nil {
			t.Fatal(err)
		}
		req.Header.Set("Authorization", "Bearer "+raw)
		for _, f := range v.formats {
			req.Header.Add(formatgate.HeaderName, f)
		}
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			t.Fatal(err)
		}
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("GET /v1/smart-playlists answered %d", resp.StatusCode)
		}
		var sp smartPlaylistsResponse
		if err := json.NewDecoder(resp.Body).Decode(&sp); err != nil {
			t.Fatal(err)
		}
		for _, p := range sp.Playlists {
			if p.Kind != christmasKind {
				continue
			}
			paths := make([]string, 0, len(p.Items))
			for i, it := range p.Items {
				if it.Position != i {
					t.Errorf("view %s: item %d at position %d, want the positions closed up", v.name, i, it.Position)
				}
				paths = append(paths, it.Path)
			}
			return paths, true
		}
		return nil, false
	}
}

// requireSentExactly fails unless the view is sent the family holding exactly
// want, in any order.
func requireSentExactly(t *testing.T, v xmasView, got []string, sent bool, want []string) {
	t.Helper()
	if !sent {
		t.Errorf("view %s: the family is not sent, want it with its %d tracks", v.name, len(want))
		return
	}
	if !slices.Equal(slices.Sorted(slices.Values(got)), slices.Sorted(slices.Values(want))) {
		t.Errorf("view %s: sent %d items %v, want exactly the %d tracks %v", v.name, len(got), got, len(want), want)
	}
}

// The review's library: fifteen FLACs, five each by three choirs on three
// albums, beside a thousand WavPack singles. Shuffled and capped as one pool,
// the thousand took the cap and a client that declares neither format lost
// the family though fifteen qualifying tracks exist, all season. Now every
// view is sent the fifteen FLACs, first, and a view that declares WavPack the
// rest of the cap from its files.
func TestTheChristmasFamilyFillsFromWhatEveryViewCanPlayFirst(t *testing.T) {
	var tracks []*manifest.Track
	for i, a := range []string{"Carols A", "Carols B", "Carols C"} {
		tracks = append(tracks, xmasAlbumOf(a, a, ".flac", 5, byOne(fmt.Sprintf("Choir %d", i)))...)
	}
	flacs := pathsOfTracks(tracks)
	tracks = append(tracks, xmasSingles("WavPack", ".wv", 1000)...)
	get := xmasViewsServer(t, tracks)
	for _, v := range xmasViews {
		got, sent := get(t, v)
		if !v.takes("x.wv") {
			requireSentExactly(t, v, got, sent, flacs)
			continue
		}
		if !sent || len(got) != 100 {
			t.Errorf("view %s: sent %v with %d items, want the cap, 100", v.name, sent, len(got))
			continue
		}
		requireSentExactly(t, v, got[:15], sent, flacs)
		for i, p := range got[15:] {
			if path.Ext(p) != ".wv" {
				t.Errorf("view %s: item %d is %s, want a WavPack file after the FLACs", v.name, 15+i, p)
			}
		}
	}
}

// A view the gate leaves below the floor is not sent the family, though the
// whole pool clears it and a view that declares the gated format is sent it:
// fourteen FLACs beside WavPack files, and fifteen FLACs by two artists on two
// albums beside WavPack files by others.
func TestAViewLeftBelowTheChristmasFloorIsNotSentTheFamily(t *testing.T) {
	t.Run("14 FLACs beside WavPack files", func(t *testing.T) {
		tracks := append(append(append(
			xmasAlbumOf("Carols A", "Carols A", ".flac", 5, byOne("Choir A")),
			xmasAlbumOf("Carols B", "Carols B", ".flac", 5, byOne("Choir B"))...),
			xmasAlbumOf("Carols C", "Carols C", ".flac", 4, byOne("Choir C"))...),
			xmasSingles("WavPack", ".wv", 20)...)
		get := xmasViewsServer(t, tracks)
		for _, v := range xmasViews {
			got, sent := get(t, v)
			if v.takes("x.wv") {
				requireSentExactly(t, v, got, sent, pathsOfTracks(tracks))
			} else if sent {
				t.Errorf("view %s: sent the family with %d items, want none: 14 tracks are below the floor", v.name, len(got))
			}
		}
	})
	t.Run("15 FLACs by two artists on two albums beside WavPack files by others", func(t *testing.T) {
		tracks := append(append(
			xmasAlbumOf("Duo A", "Duo A", ".flac", 8, byOne("Singer A")),
			xmasAlbumOf("Duo B", "Duo B", ".flac", 7, byOne("Singer B"))...),
			xmasSingles("WavPack", ".wv", 10)...)
		get := xmasViewsServer(t, tracks)
		for _, v := range xmasViews {
			got, sent := get(t, v)
			if v.takes("x.wv") {
				requireSentExactly(t, v, got, sent, pathsOfTracks(tracks))
			} else if sent {
				t.Errorf("view %s: sent the family with %d items, want none: two artists on two albums are below the floor", v.name, len(got))
			}
		}
	})
}

// Fifteen FLACs by one artist across three albums clear the floor, and so do
// fifteen FLACs on one album by three artists: 3 albums or 3 artists. Beside
// them, five WavPack and five Monkey's Audio singles by others.
func TestAChristmasFamilyOfOneArtistOrOneAlbumClearsTheFloorInEveryView(t *testing.T) {
	for _, c := range []struct {
		name  string
		flacs []*manifest.Track
	}{
		{"one artist across three albums", append(append(
			xmasAlbumOf("Choir/A", "Advent", ".flac", 5, byOne("Choir")),
			xmasAlbumOf("Choir/B", "Bethlehem", ".flac", 5, byOne("Choir"))...),
			xmasAlbumOf("Choir/C", "Carols", ".flac", 5, byOne("Choir"))...)},
		{"one album by three artists", xmasAlbumOf("Gathering", "A Christmas Gathering", ".flac", 15,
			func(i int) string { return []string{"Bing", "Ella", "Nat"}[i%3] })},
	} {
		t.Run(c.name, func(t *testing.T) {
			tracks := append(append(append([]*manifest.Track{}, c.flacs...),
				xmasSingles("WavPack", ".wv", 5)...), xmasSingles("APE", ".ape", 5)...)
			get := xmasViewsServer(t, tracks)
			for _, v := range xmasViews {
				var want []string
				for _, p := range pathsOfTracks(tracks) {
					if v.takes(p) {
						want = append(want, p)
					}
				}
				got, sent := get(t, v)
				requireSentExactly(t, v, got, sent, want)
			}
		})
	}
}

// A thousand WavPack singles beside fifteen Monkey's Audio files by three
// choirs: a client that declares Monkey's Audio is sent its fifteen, one that
// declares WavPack the 85 the cap leaves, one that declares nothing no
// family, and one that declares both the whole cap.
func TestAThousandWavPackFilesLeaveTheAPEViewItsFifteen(t *testing.T) {
	var apes []*manifest.Track
	for i, a := range []string{"APE A", "APE B", "APE C"} {
		apes = append(apes, xmasAlbumOf(a, a, ".ape", 5, byOne(fmt.Sprintf("Choir %d", i)))...)
	}
	tracks := append(append([]*manifest.Track{}, apes...), xmasSingles("WavPack", ".wv", 1000)...)
	get := xmasViewsServer(t, tracks)
	for _, v := range xmasViews {
		got, sent := get(t, v)
		switch v.name {
		case "nothing":
			if sent {
				t.Errorf("view %s: sent the family with %d items, want none", v.name, len(got))
			}
		case "APE":
			requireSentExactly(t, v, got, sent, pathsOfTracks(apes))
		case "WavPack":
			if !sent || len(got) != 85 {
				t.Errorf("view %s: sent %v with %d items, want the 85 WavPack files the cap leaves", v.name, sent, len(got))
			}
		case "both":
			var ape int
			for _, p := range got {
				if path.Ext(p) == ".ape" {
					ape++
				}
			}
			if !sent || len(got) != 100 || ape != 15 {
				t.Errorf("view %s: sent %v with %d items, %d of them .ape; want the cap, 100, every .ape among them", v.name, sent, len(got), ape)
			}
		}
	}
}

// A family cached before its items stored their album has none, and is
// judged on its artists until the next build stores them: fifteen tracks by
// one artist across three albums are then below the floor, where the same
// family with its albums clears it, and fifteen tracks by three artists clear
// it either way.
func TestAChristmasFamilyCachedWithoutAlbumsIsJudgedOnItsArtists(t *testing.T) {
	blob := func(withAlbums bool, artistOf func(int) string) []byte {
		t.Helper()
		type item struct {
			Position int    `json:"position"`
			Path     string `json:"path"`
			Title    string `json:"title,omitempty"`
			Artist   string `json:"artist,omitempty"`
			Album    string `json:"album,omitempty"`
		}
		var items []item
		for i := 0; i < 15; i++ {
			album := []string{"Advent", "Bethlehem", "Carols"}[i/5]
			it := item{Position: i, Path: fmt.Sprintf("Choir/%s/%02d.flac", album, i), Title: "Carol", Artist: artistOf(i)}
			if withAlbums {
				it.Album = album
			}
			items = append(items, it)
		}
		raw, err := json.Marshal(items)
		if err != nil {
			t.Fatal(err)
		}
		return raw
	}
	for _, c := range []struct {
		name  string
		items []byte
		want  bool
	}{
		{"one artist across three albums, cached without albums", blob(false, byOne("Choir")), false},
		{"one artist across three albums, cached with them", blob(true, byOne("Choir")), true},
		{"three artists, cached without albums", blob(false, func(i int) string { return []string{"Bing", "Ella", "Nat"}[i%3] }), true},
	} {
		t.Run(c.name, func(t *testing.T) {
			mstore := openFeedStore(t)
			if err := mstore.ReplaceSmartPlaylists(context.Background(), []manifest.StoredSmartPlaylist{
				{Slug: "christmas", Kind: christmasKind, Title: "Christmas", Position: 0, RefreshedAt: 1, ItemsJSON: c.items},
			}); err != nil {
				t.Fatal(err)
			}
			get := xmasFeedOf(t, mstore)
			for _, v := range xmasViews {
				if _, sent := get(t, v); sent != c.want {
					t.Errorf("view %s: the family sent %v, want %v", v.name, sent, c.want)
				}
			}
		})
	}
}
